package com.yuegang.zhihui.system.security;
import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.common.security.*;import jakarta.servlet.http.*;import java.time.*;
public final class InternalServiceVerifier{private final InternalServiceSignature signatures;public InternalServiceVerifier(byte[]s,Clock c){signatures=new InternalServiceSignature(s,c,Duration.ofSeconds(30));}public void verify(HttpServletRequest r,String expected){try{String service=h(r,"X-YGH-Service");if(!expected.equals(service))throw fail();Instant t=Instant.ofEpochMilli(Long.parseLong(h(r,"X-YGH-Service-Timestamp")));var m=new InternalServiceSignature.Metadata(service,r.getMethod(),r.getRequestURI(),t);if(!signatures.verify(m,h(r,"X-YGH-Service-Signature")))throw fail();}catch(BusinessException e){throw e;}catch(RuntimeException e){throw fail();}}private static String h(HttpServletRequest r,String n){String v=r.getHeader(n);if(v==null||v.isBlank())throw fail();return v;}private static BusinessException fail(){return new BusinessException(ErrorCode.UNAUTHENTICATED);}}
